ValidationRule.errorConditionFormula:
!$Setup.Bypass_Automation_Setting__c.Foundation_Code_Validation__c &&
OR(
AND(
ISPICKVAL(Type__c ,'Parent Initiative'),ISBLANK(Initiative__c) 
),
AND(
ISPICKVAL(Type__c ,'Budgeted Initiative'),ISBLANK(Initiative__c) 
),
AND(
ISPICKVAL(Type__c ,'Focus Area Misc'),ISBLANK(Initiative__c) 
),
AND(
ISPICKVAL(Type__c ,'Miscellaneous Initiative'),ISBLANK(Initiative__c) 
)

)
